int search(int *arr, int arrSize, int target) {
  int lo = 0, hi = arrSize - 1, res = -1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) / 2;
    if (arr[mid] == target) {
      res = mid;
      hi = mid - 1;
    } else if (arr[mid] > arr[lo]) {
      if (target >= arr[lo] && target < arr[mid]) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else if (arr[mid] < arr[lo]) {
      if (target > arr[mid] && target <= arr[hi]) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    } else {
      if (arr[lo] != target) {
        lo++;
      } else {
        res = mid;
        hi = mid - 1;
      }
    }
  }
  return res;
}

