class Solution:
    def search(self, arr: List[int], target: int) -> int:
        lo, hi, res = 0, len(arr) - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                res = mid
                hi = mid - 1
            elif arr[mid] > arr[lo]:
                if arr[lo] <= target < arr[mid]:
                    hi = mid - 1
                else:
                    lo = mid + 1
            elif arr[mid] < arr[lo]:
                if arr[mid] < target <= arr[hi]:
                    lo = mid + 1
                else:
                    hi = mid - 1
            else:
                if arr[lo] != target:
                    lo += 1
                else:
                    res = mid
                    hi = mid - 1
        return res

impl Solution {
  pub fn search(arr: Vec<i32>, target: i32) -> i32 {
    let (mut lo, mut hi, mut res) = (0i32, arr.len() as i32 - 1, -1);
    while lo <= hi {
      let mid = lo + (hi - lo) / 2;
      let (l, m, h) = (arr[lo as usize], arr[mid as usize], arr[hi as usize]);
      if m == target {
        res = mid;
        hi = mid - 1;
      } else if m > l {
        if target >= l && target < m {
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      } else if m < l {
        if target > m && target <= h {
          lo = mid + 1;
        } else {
          hi = mid - 1;
        }
      } else if l != target {
        lo += 1;
      } else {
        res = mid;
        hi = mid - 1;
      }
    }
    res
  }
}

const search = (arr: number[], target: number): number => {
  let lo = 0;
  let hi = arr.length - 1;
  let res = -1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] === target) {
      res = mid;
      hi = mid - 1;
    } else if (arr[mid] > arr[lo]) {
      if (target >= arr[lo] && target < arr[mid]) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else if (arr[mid] < arr[lo]) {
      if (target > arr[mid] && target <= arr[hi]) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    } else {
      if (arr[lo] !== target) {
        lo++;
      } else {
        res = mid;
        hi = mid - 1;
      }
    }
  }
  return res;
};
